    public void SetCurriculumGoal(Vector2 worldGoal,Vector2 heading,int deadlineTick){externalTrainingGoal=true;externalWorldGoal=worldGoal;externalWorldHeading=NormalizeHeading(heading,Vector2.up);externalGoalTicks=deadlineTick;hasGoal=true;}
