    public NativeActionSequence OptimizeAndPlan(NativeObservation observation,NativeDynamicsWeights sharedM3,int sharedM3Samples)
    {TrainM2Batch(new[]{observation},sharedM3,observation.tick);return Plan(observation,sharedM3,sharedM3Samples);}

    public NativeM2BatchMetrics TrainM2Batch(IReadOnlyList<NativeObservation> source,NativeDynamicsWeights sharedM3,int currentTick)
    {
