        foreach(NativeObservation observation in samples){var cache=ForwardM2(observation,next);float frequency,phase;float[,] decoderGradient;float[,] actions=DecodeRhythmicActions(cache.actions,observation,bias,out frequency,out phase,out decoderGradient);var predicted=ForwardM3(observation,actions,sharedM3);float[] pg=new float[M3OutputSize];float loss=M2Loss(predicted.prediction,observation.goal,observation.goalHeading,actions,observation.limbCount,pg,out float goalLoss,out float energyLoss);float[,] ag=BackwardM3(predicted,pg,null,sharedM3,null);AddEnergyGradient(ag,actions,observation.limbCount);for(int s=0;s<PlanningHorizon;s++)for(int l=0;l<observation.limbCount;l++)ag[s,l]*=decoderGradient[s,l];BackwardM2(cache,ag,next,gradient);metrics.loss+=loss;metrics.goalLoss+=goalLoss;metrics.energyLoss+=energyLoss;}
        foreach(float[] values in gradient.Values)for(int i=0;i<values.Length;i++)values[i]/=samples.Count;ApplyAdam(next.M2Parameters(),gradient,optimizer,M2LearningRate,protection);if(!next.IsFinite()||!protection.IsFinite())throw new InvalidOperationException("M2 update produced non-finite state");lock(trainingStateLock){Weights=next;M2Optimizer=optimizer;M2Protection=protection;}metrics.loss/=samples.Count;metrics.goalLoss/=samples.Count;metrics.energyLoss/=samples.Count;metrics.optimizerSteps=optimizer.step;return metrics;
    }

    public static NativeM3BatchMetrics TrainSharedM3Batch(IReadOnlyList<NativeCompletedSequence> source,NativeDynamicsWeights weights,NativeOptimizerState optimizer,NativeSynapticIntelligence protection=null)
    {var samples=(source??Array.Empty<NativeCompletedSequence>()).Where(s=>s?.observation!=null).OrderBy(s=>s.sampleId??string.Empty,StringComparer.Ordinal).ThenBy(s=>s.observation.tick).ToList();var metrics=new NativeM3BatchMetrics{sampleCount=samples.Count};if(samples.Count==0)return metrics;var gradients=Zero(weights.Parameters());foreach(var sample in samples){var cache=ForwardM3(sample.observation,sample.ActionMatrix(),weights);float[] pg=new float[M3OutputSize],ag=new float[M3AuxiliaryOutputSize];float pose=M3Loss(cache.prediction,sample.actualPoses,pg,out float mse,out float relative),aux=M3AuxiliaryLoss(cache.auxiliary,sample.actualAuxiliary,ag,sample.observation.limbCount,out float endpoint,out float contact);BackwardM3(cache,pg,ag,weights,gradients);metrics.loss+=pose+aux;metrics.poseMse+=mse;metrics.relativeLoss+=relative;metrics.velocityLoss+=endpoint;metrics.contactLoss+=contact;}foreach(float[] values in gradients.Values)for(int i=0;i<values.Length;i++)values[i]/=samples.Count;ApplyAdam(weights.Parameters(),gradients,optimizer,M3LearningRate,protection);metrics.loss/=samples.Count;metrics.poseMse/=samples.Count;metrics.relativeLoss/=samples.Count;metrics.velocityLoss/=samples.Count;metrics.contactLoss/=samples.Count;metrics.optimizerSteps=optimizer.step;return metrics;}

