[Serializable] public sealed class NativeDeterministicRng{public ulong State;public NativeDeterministicRng():this(1UL){}public NativeDeterministicRng(ulong seed){State=seed==0?1UL:seed;}private ulong NextRaw(){State^=State<<13;State^=State>>7;State^=State<<17;return State;}public ulong NextUInt64()=>NextRaw();public float NextFloat()=>((NextRaw()>>40)&0xFFFFFF)/(float)0x1000000;public int NextInt(int exclusiveMax){if(exclusiveMax<=0)throw new ArgumentOutOfRangeException(nameof(exclusiveMax));uint bound=(uint)exclusiveMax,threshold=unchecked(0u-bound)%bound;uint value;do{value=(uint)NextRaw();}while(value<threshold);return (int)(value%bound);}public long NextLong(long exclusiveMax){if(exclusiveMax<=0)throw new ArgumentOutOfRangeException(nameof(exclusiveMax));ulong bound=(ulong)exclusiveMax,threshold=unchecked(0UL-bound)%bound,value;do{value=NextRaw();}while(value<threshold);return (long)(value%bound);}}
